// Small 53-bit string hash, no external library needed
function hash53(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

// Remove HTML tags and common HTML entities
function stripHtml(s) {
  return String(s || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const link = j.link || '';
  let title = stripHtml(j.title);
  if (!title) continue;

  // Google News titles end with " - Source name": remove it
  if (link.includes('news.google.com')) title = title.replace(/\s+-\s+[^-]+$/, '');

  // Normalised title = basis of the fingerprint
  const normTitle = title.toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const content_hash = hash53(normTitle);
  if (seen.has(content_hash)) continue;   // duplicate inside this same batch
  seen.add(content_hash);

  const summary = stripHtml(j.contentSnippet || j.content || j.description || '').slice(0, 600);

  let published = new Date(j.isoDate || j.pubDate || Date.now());
  if (isNaN(published)) published = new Date();

  out.push({ json: {
    content_hash,
    title,
    url: link,
    summary,
    published_at: published.toISOString(),
  }});
}

return out;

