const extraction_failed = !$json.output;   // LLM error (e.g. rate limit) → retry later
const out = $json.output || {};
const art = $('New article?').item.json;

// --- helpers ---
const SUFFIXES = new Set(['inc','incorporated','corp','corporation','co','company','ltd','limited',
  'plc','llc','lp','sa','sas','se','ag','gmbh','nv','bv','spa','ab','asa','oyj',
  'group','holding','holdings','the']);

// "Microsoft Corp." and "Microsoft Corporation" both become "microsoft"
function normName(s) {
  return String(s || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9 ]/g, ' ')
    .split(/\s+/).filter(w => w && !SUFFIXES.has(w))
    .join(' ');
}
const clean = s => String(s ?? '').trim();
const EMPTY = ['', 'unknown', 'n/a', 'na', 'none', 'not disclosed', 'undisclosed'];
const errors = [];

// --- parties ---
const acquirer = clean(out.acquirer);
const target = clean(out.target);
if (EMPTY.includes(acquirer.toLowerCase())) errors.push('missing acquirer');
if (EMPTY.includes(target.toLowerCase())) errors.push('missing target');
const aKey = normName(acquirer), tKey = normName(target);
if (aKey && aKey === tKey) errors.push('acquirer equals target');

// --- type and status: only allowed values ---
const TYPES = ['acquisition','merger','majority_stake','minority_stake','asset_purchase','other'];
const STATUSES = ['announced','pending','completed','terminated','rumoured'];
let deal_type = clean(out.deal_type).toLowerCase();
if (!TYPES.includes(deal_type)) deal_type = 'other';
let status = clean(out.status).toLowerCase();
if (!STATUSES.includes(status)) status = 'announced';

// --- value and currency: 0 or nonsense becomes empty ---
let value = Number(out.value_millions);
if (!isFinite(value) || value <= 0 || value > 2000000) value = '';
let currency = clean(out.currency).toUpperCase();
if (value === '' || !/^[A-Z]{3}$/.test(currency)) currency = '';

// --- date: must be valid and not in the future, else use the article date ---
let announced_date = clean(out.announced_date);
const d = new Date(announced_date);
const tomorrow = Date.now() + 86400000;
if (!/^\d{4}-\d{2}-\d{2}$/.test(announced_date) || isNaN(d) || d.getTime() > tomorrow || d.getFullYear() < 2000) {
  announced_date = String(art.published_at || '').slice(0, 10);
}

// --- confidence: number between 0 and 1 ---
let confidence = Number(out.confidence);
if (!isFinite(confidence)) confidence = 0.5;
confidence = Math.round(Math.min(1, Math.max(0, confidence)) * 100) / 100;
if (confidence < 0.5) errors.push('low confidence');

// --- deal key: for mergers, order does not matter ---
const deal_key = deal_type === 'merger'
  ? [aKey, tKey].sort().join('|')
  : `${aKey}|${tKey}`;

return { json: {
  valid: errors.length === 0,
  errors: errors.join(', '),
  deal_key,
  acquirer,
  target,
  target_description: clean(out.target_description).slice(0, 200),
  deal_type,
  status,
  value_m: value === '' ? '' : String(value),
  currency,
  geography: clean(out.geography).slice(0, 80),
  announced_date,
  rationale: clean(out.rationale).slice(0, 300),
  confidence: String(confidence),
  source_url: art.url || '',
  article_id: String(art.id),
}};

const google = (q, region = 'US') => {
  const r = {
    US: 'hl=en-US&gl=US&ceid=US:en',
    GB: 'hl=en-GB&gl=GB&ceid=GB:en',
  }[region];
  return `https://news.google.com/rss/search?q=${encodeURIComponent(q)}&${r}`;
};

const feeds = [
  'https://www.prnewswire.com/rss/financial-services-latest-news/acquisitions-mergers-and-takeovers-list.rss',
  google('"agrees to acquire" when:2d'),
  google('"to acquire" billion when:2d'),
  google('"merger agreement" when:2d'),
  google('"takeover bid" OR "takeover offer" when:2d', 'GB'),
  google('"majority stake" acquire when:2d'),
];

return feeds.map(url => ({ json: { url } }));

const seen = new Set(
  $input.all().map(i => i.json.content_hash).filter(Boolean)
);

return $('Clean&hash').all().filter(i => !seen.has(i.json.content_hash));
